72	  public void registerTimeseries(
73	      final String path, final List<IMeasurementSchema> measurementSchemaList) {
74	    if (device2MeasurementSchema.containsKey(path)) {
75	      LOGGER.error("Register same device {}.", path);
76	      return;
77	    }
78	    writer.registerTimeseries(new Path(path), measurementSchemaList);
79	    device2TimeSet.put(path, new TreeSet<>());
80	    device2MeasurementSchema.put(path, measurementSchemaList);
81	  }
82	
83	  public void registerAlignedTimeseries(
84	      final String path, final List<IMeasurementSchema> measurementSchemaList)
85	      throws WriteProcessException {
86	    if (device2MeasurementSchema.containsKey(path)) {
87	      LOGGER.error("Register same device {}.", path);
88	      return;
89	    }
90	    writer.registerAlignedTimeseries(new Path(path), measurementSchemaList);
91	    device2TimeSet.put(path, new TreeSet<>());
92	    device2MeasurementSchema.put(path, measurementSchemaList);
93	  }
94	
95	  public void generateData(
96	      final String device, final int number, final long timeGap, final boolean isAligned)
97	      throws IOException, WriteProcessException {
98	    final List<IMeasurementSchema> schemas = device2MeasurementSchema.get(device);
99	    final TreeSet<Long> timeSet = device2TimeSet.get(device);
100	    final Tablet tablet = new Tablet(device, schemas);
101	    final long[] timestamps = tablet.timestamps;
102	    final Object[] values = tablet.values;
103	    final long sensorNum = schemas.size();
104	    long startTime = timeSet.isEmpty() ? 0L : timeSet.last();
105	
106	    for (long r = 0; r < number; r++) {
107	      int row = tablet.getRowSize();
108	      startTime += timeGap;
109	      tablet.addTimestamp(row, startTime);
110	      timeSet.add(startTime);
111	      for (int i = 0; i < sensorNum; i++) {
112	        generateDataPoint(values[i], row, schemas.get(i));
113	      }
114	      // write
115	      if (tablet.getRowSize() == tablet.getMaxRowNumber()) {
116	        if (!isAligned) {
117	          writer.writeTree(tablet);
118	        } else {
119	          writer.writeAligned(tablet);
120	        }
121	        tablet.reset();
122	      }
123	    }
124	    // write
125	    if (tablet.getRowSize() != 0) {
126	      if (!isAligned) {
127	        writer.writeTree(tablet);
128	      } else {
129	        writer.writeAligned(tablet);
130	      }
131	      tablet.reset();
132	    }
133	
134	    LOGGER.info("Write {} points into device {}", number, device);
135	  }
